const p = $input.item.json;

// IMAGE: cover é sempre media_url (URL direta da imagem).
// thumbnail_url normalmente não é retornado para posts de imagem.
const coverSourceUrl = p.media_url || null;

return {
  json: {
    post_id:          p.id          || '18115485343992680',
    username:         'costurandosucesso',
    media_type:       p.media_type  || 'DESCONHECIDO',
    permalink:        p.permalink   || null,
    timestamp:        p.timestamp   || null,
    thumbnail_url_presente: !!p.thumbnail_url,
    media_url_presente:     !!p.media_url,
    cover_source_url: coverSourceUrl,
    cover_strategy:   'IMAGE → media_url',
    status_url:       coverSourceUrl ? 'URL_PRESENTE' : 'SEM_URL',
    erro_api:         p.error ? JSON.stringify(p.error) : null
  }
};

const p = $input.item.json;

// VIDEO/Reel: APENAS thumbnail_url é usada como capa.
// media_url aponta para o arquivo de vídeo — NUNCA deve ser usada como imagem de capa.
// Se thumbnail_url estiver ausente, reportar SEM_THUMBNAIL (não fazer fallback para media_url).
const coverSourceUrl = p.thumbnail_url || null;

return {
  json: {
    post_id:          p.id          || '18082958183373773',
    username:         'eduardocristianoriginal',
    media_type:       p.media_type  || 'DESCONHECIDO',
    permalink:        p.permalink   || null,
    timestamp:        p.timestamp   || null,
    thumbnail_url_presente: !!p.thumbnail_url,
    media_url_presente:     !!p.media_url,
    media_url_descartada:   !!p.media_url,
    cover_source_url: coverSourceUrl,
    cover_strategy:   'VIDEO → thumbnail_url APENAS (media_url descartada — arquivo de vídeo)',
    status_url:       coverSourceUrl ? 'URL_PRESENTE' : 'SEM_THUMBNAIL',
    erro_api:         p.error ? JSON.stringify(p.error) : null
  }
};

const p = $input.item.json;

const firstChild = p.children?.data?.[0] || null;
let coverSourceUrl = null;
let coverStrategy  = 'CAROUSEL → nenhum filho retornado pela API';
let firstChildInfo = null;

if (firstChild) {
  firstChildInfo = {
    child_id:              firstChild.id,
    child_media_type:      firstChild.media_type,
    child_media_url_presente:    !!firstChild.media_url,
    child_thumbnail_url_presente: !!firstChild.thumbnail_url
  };

  if (firstChild.media_type === 'VIDEO') {
    // Filho VIDEO: APENAS thumbnail_url do filho é válida como imagem de capa.
    // media_url do filho VIDEO aponta para arquivo de vídeo — descartada.
    coverSourceUrl = firstChild.thumbnail_url || null;
    coverStrategy  = 'CAROUSEL → filho[0] é VIDEO → thumbnail_url do filho APENAS';
    if (!coverSourceUrl) {
      coverStrategy += ' — thumbnail_url ausente no filho VIDEO';
    }
  } else {
    // Filho IMAGE: media_url do filho é a URL direta da imagem de capa.
    coverSourceUrl = firstChild.media_url || null;
    coverStrategy  = 'CAROUSEL → filho[0] é IMAGE → media_url do filho';
  }
}

// Fallback para media_url do álbum SÓ se o filho for IMAGE e media_url do filho ausente.
// NÃO aplicar fallback se o filho for VIDEO (media_url do álbum pode ser o próprio vídeo).
if (!coverSourceUrl && firstChild?.media_type !== 'VIDEO') {
  coverSourceUrl = p.media_url || null;
  if (coverSourceUrl) {
    coverStrategy += ' → fallback: media_url do álbum';
  }
}

const totalFilhos = p.children?.data?.length || 0;

return {
  json: {
    post_id:          p.id          || '18066040568539014',
    username:         'eduardocristianoriginal',
    media_type:       p.media_type  || 'DESCONHECIDO',
    permalink:        p.permalink   || null,
    timestamp:        p.timestamp   || null,
    thumbnail_url_presente: !!p.thumbnail_url,
    media_url_presente:     !!p.media_url,
    total_filhos:     totalFilhos,
    primeiro_filho:   firstChildInfo,
    cover_source_url: coverSourceUrl,
    cover_strategy:   coverStrategy,
    status_url:       coverSourceUrl ? 'URL_PRESENTE' : 'SEM_URL',
    erro_api:         p.error ? JSON.stringify(p.error) : null
  }
};

// Combinar dados da análise (nó anterior na chain: Analisar IMAGE)
// com resultado do HEAD (nó anterior imediato: Verificar Content-Type IMAGE)
const analise = $('Analisar IMAGE').item.json;
const head    = $input.item.json;

// fullResponse: o n8n coloca status em statusCode e headers em headers
const httpStatus  = head?.statusCode || head?.status || null;
const contentType = head?.headers?.['content-type'] || head?.headers?.['Content-Type'] || null;
const ehImagem    = contentType ? contentType.startsWith('image/') : null;

return {
  json: {
    post_id:              analise.post_id,
    username:             analise.username,
    media_type:           analise.media_type,
    cover_strategy:       analise.cover_strategy,
    status_url:           analise.status_url,
    head_http_status:     httpStatus,
    content_type:         contentType,
    content_type_valido:  ehImagem,
    status_final:         !analise.cover_source_url ? 'SEM_URL'
                          : (ehImagem === true  ? 'OK'
                          : (ehImagem === false ? 'URL_NAO_EH_IMAGEM'
                          :                      'HEAD_FALHOU')),
    thumbnail_url_presente: analise.thumbnail_url_presente,
    media_url_presente:     analise.media_url_presente,
    erro_api:             analise.erro_api
  }
};

const analise = $('Analisar VIDEO').item.json;
const head    = $input.item.json;

const httpStatus  = head?.statusCode || head?.status || null;
const contentType = head?.headers?.['content-type'] || head?.headers?.['Content-Type'] || null;
const ehImagem    = contentType ? contentType.startsWith('image/') : null;

return {
  json: {
    post_id:              analise.post_id,
    username:             analise.username,
    media_type:           analise.media_type,
    cover_strategy:       analise.cover_strategy,
    status_url:           analise.status_url,
    head_http_status:     httpStatus,
    content_type:         contentType,
    content_type_valido:  ehImagem,
    status_final:         analise.status_url === 'SEM_THUMBNAIL' ? 'SEM_THUMBNAIL'
                          : (ehImagem === true  ? 'OK'
                          : (ehImagem === false ? 'URL_NAO_EH_IMAGEM'
                          :                      'HEAD_FALHOU')),
    thumbnail_url_presente: analise.thumbnail_url_presente,
    media_url_presente:     analise.media_url_presente,
    media_url_descartada:   analise.media_url_descartada,
    erro_api:             analise.erro_api
  }
};

const analise = $('Analisar CAROUSEL').item.json;
const head    = $input.item.json;

const httpStatus  = head?.statusCode || head?.status || null;
const contentType = head?.headers?.['content-type'] || head?.headers?.['Content-Type'] || null;
const ehImagem    = contentType ? contentType.startsWith('image/') : null;

return {
  json: {
    post_id:              analise.post_id,
    username:             analise.username,
    media_type:           analise.media_type,
    cover_strategy:       analise.cover_strategy,
    status_url:           analise.status_url,
    head_http_status:     httpStatus,
    content_type:         contentType,
    content_type_valido:  ehImagem,
    status_final:         !analise.cover_source_url ? 'SEM_URL'
                          : (ehImagem === true  ? 'OK'
                          : (ehImagem === false ? 'URL_NAO_EH_IMAGEM'
                          :                      'HEAD_FALHOU')),
    total_filhos:         analise.total_filhos,
    primeiro_filho:       analise.primeiro_filho,
    thumbnail_url_presente: analise.thumbnail_url_presente,
    media_url_presente:     analise.media_url_presente,
    erro_api:             analise.erro_api
  }
};

const items = $input.all();

const porStatus = (s) => items.filter(i => i.json.status_final === s).length;
const ok            = porStatus('OK');
const semUrl        = porStatus('SEM_URL');
const semThumb      = porStatus('SEM_THUMBNAIL');
const naoEhImagem   = porStatus('URL_NAO_EH_IMAGEM');
const headFalhou    = porStatus('HEAD_FALHOU');
const comErroApi    = items.filter(i => i.json.erro_api).length;

const resultado_geral =
  ok === items.length    ? 'APROVADO — todas as capas são imagens válidas' :
  comErroApi > 0         ? 'ERRO_API — verificar campo erro_api' :
  naoEhImagem > 0        ? 'REPROVADO — URL presente mas Content-Type não é image/*' :
  semThumb > 0           ? 'PARCIAL — Reel sem thumbnail_url (sem fallback para media_url)' :
  semUrl > 0             ? 'PARCIAL — algum post sem URL de capa' :
                           'VERIFICAR — HEAD inconclusivo';

const detalhes = items.map(i => {
  const j = i.json;
  return {
    post_id:              j.post_id,
    username:             j.username,
    media_type:           j.media_type,
    cover_strategy:       j.cover_strategy,
    head_http_status:     j.head_http_status,
    content_type:         j.content_type,
    content_type_valido:  j.content_type_valido,
    status_final:         j.status_final,
    thumbnail_url_presente: j.thumbnail_url_presente,
    media_url_presente:     j.media_url_presente,
    media_url_descartada:   j.media_url_descartada ?? null,
    total_filhos:           j.total_filhos ?? null,
    primeiro_filho_tipo:    j.primeiro_filho?.child_media_type ?? null,
    erro_api:             j.erro_api || null
  };
});

return {
  json: {
    poc_summary: {
      total:            items.length,
      ok:               ok,
      sem_url:          semUrl,
      sem_thumbnail:    semThumb,
      url_nao_eh_imagem: naoEhImagem,
      head_falhou:      headFalhou,
      com_erro_api:     comErroApi,
      resultado_geral:  resultado_geral
    },
    detalhes: detalhes,
    _nota: 'URLs brutas da Meta CDN não são incluídas neste relatório. Para inspecionar uma URL específica, abrir o nó Analisar correspondente nos dados de execução do n8n.'
  }
};
